    (N'WF-SP-007', N'Iron Golf', N'Sports & Outdoors', N'The Iron Golf is a type of golf club designed for various golf shots. It features a solid metal head and is used for approach shots, chipping, and other golfing techniques.', 49.99, 61.49, N'/uploads/product-images/wf-sp-007_iron-golf.webp'),
    (N'WF-SP-008', N'American Football', N'Sports & Outdoors', N'The American Football is a classic ball used in American football games. It is designed for throwing and catching, making it an essential piece of equipment for the sport.', 19.99, 24.59, N'/uploads/product-images/wf-sp-008_american-football.webp'),
